#!/usr/bin/env python3
"""Validate After Action records without third-party dependencies.

The JSON Schema is the human/machine-readable contract. This validator implements
its safety-critical invariants explicitly so a clean Python installation can check
records. It does not claim to be a general-purpose JSON Schema implementation.
"""

from __future__ import annotations

import argparse
import datetime as dt
import json
import re
import sys
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
SCHEMA_PATH = ROOT / "schema" / "incident.schema.json"
STATUSES = {"reported", "not_reported", "unknown", "not_applicable", "contradicted"}
SOURCE_TYPES = {"developer", "deployer", "official", "affected_party", "secondary", "commentary"}
ACCESS_STATUSES = {"full", "limited", "snippet", "inaccessible"}
REVIEW_STATUSES = {"provisional", "double_reviewed", "adjudicated"}
ID_RE = re.compile(r"^HT-[0-9]{4}-[0-9]{3}$")
SOURCE_ID_RE = re.compile(r"^S[0-9]{3}$")


def core_fields() -> list[str]:
    schema = json.loads(SCHEMA_PATH.read_text(encoding="utf-8"))
    return list(schema["properties"]["fields"]["required"])


def is_date(value: Any) -> bool:
    if not isinstance(value, str):
        return False
    try:
        dt.date.fromisoformat(value)
        return True
    except ValueError:
        return False


def nonempty(value: Any) -> bool:
    return value is not None and value != "" and value != [] and value != {}


def validate_record(record: Any, path: str = "<record>") -> list[str]:
    errors: list[str] = []

    def err(message: str) -> None:
        errors.append(f"{path}: {message}")

    if not isinstance(record, dict):
        return [f"{path}: record must be a JSON object"]

    required = {
        "schema_version", "incident_id", "title", "review_status", "candidate_id",
        "inclusion_rationale", "reviewer_ids", "sources", "fields", "created_at", "updated_at",
    }
    for key in sorted(required - record.keys()):
        err(f"missing required property '{key}'")
    for key in sorted(record.keys() - required):
        err(f"unexpected property '{key}'")
    if errors:
        return errors

    if record["schema_version"] != "0.1":
        err("schema_version must be '0.1'")
    if not isinstance(record["incident_id"], str) or not ID_RE.match(record["incident_id"]):
        err("incident_id must match HT-YYYY-NNN")
    if not isinstance(record["title"], str) or len(record["title"].strip()) < 8:
        err("title must contain at least eight characters")
    if record["review_status"] not in REVIEW_STATUSES:
        err(f"review_status must be one of {sorted(REVIEW_STATUSES)}")
    if not isinstance(record["candidate_id"], str) or not record["candidate_id"].strip():
        err("candidate_id must be a non-empty string")
    if not isinstance(record["inclusion_rationale"], str) or len(record["inclusion_rationale"].strip()) < 20:
        err("inclusion_rationale must explain eligibility in at least 20 characters")
    for key in ("created_at", "updated_at"):
        if not is_date(record[key]):
            err(f"{key} must be an ISO calendar date")
    if is_date(record["created_at"]) and is_date(record["updated_at"]):
        if record["updated_at"] < record["created_at"]:
            err("updated_at cannot precede created_at")

    reviewers = record["reviewer_ids"]
    if not isinstance(reviewers, list) or not reviewers or not all(
        isinstance(item, str) and item.strip() for item in reviewers
    ):
        err("reviewer_ids must be a non-empty array of non-empty strings")
        reviewers = []
    if len(set(reviewers)) != len(reviewers):
