#!/usr/bin/env python3
"""Compute pre-adjudication raw agreement from independent full review records.

Expected layout: data/reviews/HT-YYYY-NNN/reviewer-a.json, reviewer-b.json.
Only the first two distinct reviewer records are compared; additional audits belong
in a separate analysis. Chance-corrected statistics require a prespecified category
analysis and are intentionally not hidden behind a generic aggregate here.
"""

from __future__ import annotations

import json
from collections import defaultdict
from pathlib import Path
from typing import Any

from validate import ROOT, core_fields


def canonical(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def field_value(record: dict, field: str) -> str:
    evidence = record["fields"][field]
    return canonical({"status": evidence["status"], "value": evidence["value"]})


def raw_agreement(review_groups: dict[str, list[dict]]) -> dict[str, dict[str, float | int | None]]:
    results: dict[str, dict[str, float | int | None]] = {}
    for field in core_fields():
        paired = 0
        agreed = 0
        for records in review_groups.values():
            if len(records) != 2:
                continue
            paired += 1
            if field_value(records[0], field) == field_value(records[1], field):
                agreed += 1
        results[field] = {
            "paired_cases": paired,
            "agreements": agreed,
            "raw_agreement": agreed / paired if paired else None,
        }
    return results


def load_review_groups(directory: Path = ROOT / "data" / "reviews") -> dict[str, list[dict]]:
    groups: dict[str, list[dict]] = defaultdict(list)
    for path in sorted(directory.rglob("*.json")):
        record = json.loads(path.read_text(encoding="utf-8"))
        groups[record["incident_id"]].append(record)
    return groups


def main() -> int:
    groups = load_review_groups()
    complete = {key: value for key, value in groups.items() if len(value) == 2}
    incomplete = {key: len(value) for key, value in groups.items() if len(value) != 2}
    print(f"Independent review groups: {len(groups)}; exactly paired: {len(complete)}")
    if incomplete:
        print("Not included in agreement calculation (need exactly two records): " + json.dumps(incomplete, sort_keys=True))
    if not complete:
        print("No paired reviews; agreement is not defined.")
        return 0
    for field, result in raw_agreement(complete).items():
        rate = result["raw_agreement"]
        print(f"{field}: {result['agreements']}/{result['paired_cases']} = {rate:.3f}")
    print("Raw agreement only; interpret sparse and imbalanced fields cautiously.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

